<section class="winbox-child ch2-window ch2-window--list ch4-native-window" data-window="files" aria-label="File List" hidden>
    <header><span>File List</span><span class="ch2-window-controls"><button type="button" data-minimize="files" aria-label="Minimalkan">−</button><button type="button" data-maximize="files" aria-label="Maksimalkan">□</button><button type="button" data-close="files" aria-label="Tutup">×</button></span></header>
    <div class="ch2-window-toolbar ch4-native-toolbar"><button type="button" data-file-tool="remove" title="Remove" aria-label="Hapus file">−</button><button type="button" data-file-tool="backup">Backup</button><button type="button" data-file-tool="restore">Restore</button><button type="button" data-file-tool="upload">Upload...</button><input type="search" data-file-find placeholder="Find" aria-label="Cari file"><span>all</span></div>
    <div class="ch4-table ch4-files-table" data-upload-login tabindex="0" aria-label="File List, seret login.html ke tabel ini untuk mengunggah">
        <div class="ch4-table-head"><span>Name</span><span>Type</span><span>Size</span><span>Creation Time</span></div>
        <div class="ch4-data-row" data-hotspot-directory><span>▸ hotspot</span><span>directory</span><span></span><span></span></div>
        <button type="button" draggable="true" data-login-file class="ch4-data-row"><span>　hotspot/login.html</span><span>.html file</span><span data-login-file-size></span><span></span></button>
    </div><footer data-file-count>0 items</footer>
</section>
<section class="winbox-child ch2-window ch2-window--medium ch4-native-window" data-window="upload-picker" aria-label="Open" hidden><header><span>Open</span><span class="ch2-window-controls"><button type="button" data-close="upload-picker" aria-label="Tutup">×</button></span></header><div class="ch4-upload-picker"><span>Look in: Desktop</span><button type="button" data-pick-login-file>▤ login.html</button><label>File name:<input data-upload-file-name autocomplete="off"></label><label>Files of type:<select><option>All files (*.*)</option></select></label><div><button type="button" data-upload-file-open>Open</button><button type="button" data-close="upload-picker">Cancel</button></div></div></section>
